const input = $input.first()?.json ?? {};
const headers = input.headers ?? {};
const rawBody = await this.helpers.getBinaryDataBuffer(0, 'data');

const hmac = String(headers['x-shopify-hmac-sha256'] ?? headers['X-Shopify-Hmac-SHA256'] ?? '').trim();
const webhookId = String(headers['x-shopify-webhook-id'] ?? headers['X-Shopify-Webhook-Id'] ?? '').trim();
const eventId = String(headers['x-shopify-event-id'] ?? headers['X-Shopify-Event-Id'] ?? '').trim();
const shop = String(headers['x-shopify-shop-domain'] ?? headers['X-Shopify-Shop-Domain'] ?? '').trim().toLowerCase();
const secret = String($vars.SHOPIFY_CLIENT_SECRET ?? '');

function invalid(code, message, httpStatus=400) {
  return [{json:{
    valid:false,
    securityVerified:false,
    responseCode:httpStatus,
    errorCode:code,
    errorMessage:message,
    webhookId,
    eventId,
    tenantId:shop,
    correlationId:String($execution.id)
  }}];
}

if (!rawBody || !hmac || !webhookId || !shop || !secret) {
  return invalid('WEBHOOK_SECURITY_MISSING','Webhook security validation failed',401);
}

const crypto = require('crypto');
const computed = crypto.createHmac('sha256', secret)
  .update(Buffer.isBuffer(rawBody) ? rawBody : Buffer.from(String(rawBody),'utf8'))
  .digest('base64');

const a=Buffer.from(hmac,'utf8'), b=Buffer.from(computed,'utf8');
if (a.length!==b.length || !crypto.timingSafeEqual(a,b)) {
  return invalid('WEBHOOK_HMAC_INVALID','Invalid Shopify HMAC',401);
}

let body=input.body ?? {};
if (typeof body === 'string') {
  try { body=JSON.parse(body); }
  catch { return invalid('INVALID_JSON','Invalid JSON body',400); }
}

const checkout=body.checkout ?? body;
const customer=checkout.customer ?? {};
const billing=checkout.billing_address ?? {};
const shipping=checkout.shipping_address ?? {};
const address=Object.keys(shipping).length ? shipping : billing;

const rawId=String(checkout.id ?? '').trim();
if (!rawId) return invalid('CHECKOUT_ID_MISSING','Missing Shopify checkout id',400);

let checkoutGid;
if (/^gid:\/\/shopify\/AbandonedCheckout\/\d+$/.test(rawId)) {
  checkoutGid=rawId;
} else if (/^\d+$/.test(rawId)) {
  checkoutGid=`gid://shopify/AbandonedCheckout/${rawId}`;
} else {
  return invalid('CHECKOUT_ID_UNSUPPORTED','Checkout id is not a numeric ID/GID',400);
}

const first=String(address.first_name ?? customer.first_name ?? 'Customer').trim();
const last=String(address.last_name ?? customer.last_name ?? '').trim();
const customerName=`${first} ${last}`.trim() || 'Customer';
const email=String(checkout.email ?? customer.email ?? '').trim().toLowerCase();

const amount=Number(checkout.total_price ?? checkout.subtotal_price);
if(!Number.isFinite(amount) || amount<0) return invalid('AMOUNT_INVALID','Invalid checkout amount',400);

const currency=String(checkout.currency ?? checkout.presentment_currency ?? '').trim().toUpperCase();
if(!/^[A-Z]{3}$/.test(currency)) return invalid('CURRENCY_INVALID','Invalid currency',400);

const countryCode=String(address.country_code ?? billing.country_code ?? shipping.country_code ?? '').trim().toUpperCase();
let phone=String(address.phone ?? billing.phone ?? customer.phone ?? checkout.phone ?? '').replace(/\D/g,'');
if(countryCode && countryCode!=='IN') {
  return invalid('COUNTRY_UNSUPPORTED','This workflow is configured for India only',400);
}
if(phone.length===10) phone='91'+phone;
if(phone.length===11 && phone.startsWith('0')) phone='91'+phone.slice(1);
const isPhoneValid=/^91\d{10}$/.test(phone);

const pincode=String(address.zip ?? '').replace(/\D/g,'');
const city=String(address.city ?? '').trim();
const address1=String(address.address1 ?? '').trim();
const rtoReasons=[];
if(address1 && address1.length<6) rtoReasons.push('Short address');
if(pincode && !/^\d{6}$/.test(pincode)) rtoReasons.push('Invalid pincode');
const rtoRisk=rtoReasons.length?'HIGH':'LOW';

const cartUrl=String(checkout.abandoned_checkout_url ?? checkout.abandonedCheckoutUrl ?? '').trim();
if(!/^https:\/\//i.test(cartUrl)) return invalid('RECOVERY_URL_INVALID','Missing or invalid recovery URL',400);

return [{json:{
  valid:true, securityVerified:true, responseCode:202,
  tenantId:shop, webhookId, eventId, correlationId:String($execution.id),
  checkoutId:rawId, checkoutGid, customerName, email, customerPhone:phone,
  isPhoneValid, amount, formattedAmount:amount.toLocaleString('en-IN'),
  currency, countryCode:countryCode||'IN', rtoRisk,
  rtoReasons:rtoReasons.join(', ')||'None', pincode, city, cartUrl,
  operation:'abandoned_cart_nudge', state:'RECEIVED'
}}];

const input = $input.first()?.json ?? {};

if (input.demoMode !== true) {
  throw new Error('RECOVERY_MODE_INVALID: Demo Recovery Check output required');
}

const stillAbandoned = input.still_abandoned === true;

return [{
  json: {
    ...input,
    still_abandoned: stillAbandoned,
    recoveryChecked: true,
    recoveryMode: 'DEMO'
  }
}];

const d = $input.first().json;

const eligible =
  Boolean(d.still_abandoned) &&
  Boolean(d.isPhoneValid) &&
  Boolean(d.cartUrl);

let skipReason = null;

if (!d.still_abandoned) {
  skipReason = 'RECOVERED';
} else if (!d.isPhoneValid) {
  skipReason = 'INVALID_PHONE';
} else if (!d.cartUrl) {
  skipReason = 'MISSING_RECOVERY_URL';
}

return [{
  json: {
    ...d,
    eligible,
    skipReason
  }
}];

const base=$('Eligibility + Business Rules').first().json;
const input=$input.first()?.json??{};
const raw=String(input.response??input.text??input.output??'').trim();
if(!raw) throw new Error('AI_VALIDATION: empty output');
let p;
try{p=JSON.parse(raw.replace(/^```(?:json)?\s*/i,'').replace(/\s*```$/i,'').trim());}
catch{throw new Error('AI_VALIDATION: invalid JSON');}
if(!p||Array.isArray(p)||Object.keys(p).length!==1||Object.keys(p)[0]!=='whatsapp_message') throw new Error('AI_VALIDATION: schema mismatch');
const msg=String(p.whatsapp_message??'').trim();
if(!msg||msg.length>4096) throw new Error('AI_VALIDATION: invalid message length');
if(!msg.includes(base.cartUrl)) throw new Error('AI_VALIDATION: exact recovery URL missing');
if(/ (recovered|paid|payment successful|order confirmed|delivered|guaranteed|discount|offer) /i.test(msg)) throw new Error('AI_VALIDATION: unsupported transactional/offer claim');
return [{json:{...base,finalMessage:msg,attempt:1}}];

const d=$('Validate Gemini Output').first().json;
const r=$input.first()?.json??{};
const b=r.body??r;
const status=Number(r.statusCode??r.status??0);
const ok=status>=200&&status<300;
const retryable=status===429;
const unknown=status===0||status>=500;
return [{json:{...d,providerOutcome:ok?'SUCCESS':(retryable?'RETRYABLE':(unknown?'UNKNOWN':'PERMANENT')),httpStatus:status,providerMessageId:b.id??b.messageId??null,finalState:ok?'SENT':(retryable?'RETRYABLE':(unknown?'UNKNOWN':'FAILED')),errorMessage:ok?null:String(b.error??b.message??'UltraMsg request failed').replace(/[\r\n,]+/g,' ').slice(0,500)}}];

